private fun materialSymbolRounded(
    name: String,
    pathData: String,
): ImageVector = ImageVector.Builder(
    name = name,
    defaultWidth = 24.dp,
    defaultHeight = 24.dp,
    viewportWidth = 960f,
    viewportHeight = 960f,
).apply {
    group(translationY = 960f) {
        addPath(
            pathData = addPathNodes(pathData),
            fill = SolidColor(Color.Black),
        )
    }
}.build()
